#include "paint.h"
#include "../shape/shape_alloc.h"
#include "../shape/shape_internal.h"
#include "../css/color.h"

#include <math.h>
#include <stdlib.h>
#include <string.h>

#define SVG_PAINT_CACHE_SLOT_COUNT (SVG_PAINT_CACHE_MAX_GRADIENTS * 2U)
#define SVG_PAINT_MAX_TOKEN_VISITS 4194304U

typedef struct svg_cached_gradient {
    uint32_t token_index;
    double viewport_width;
    double viewport_height;
    svg_shape_paint_kind kind;
    svg_shape_spread_method spread_method;
    bool object_bounding_box;
    double coordinates[6];
    geom_affine gradient_inverse;
    size_t first_stop;
    size_t stop_count;
} svg_cached_gradient;

struct svg_paint_cache {
    uint32_t *slots;
    svg_cached_gradient *entries;
    size_t entry_count;
    size_t entry_capacity;
};

void svg_paint_cache_destroy(svg_paint_cache *cache)
{
    if (cache == NULL) return;
    svg_shape_free(cache->slots);
    svg_shape_free(cache->entries);
    svg_shape_free(cache);
}

const geom_edge *svg_paint_edge_span(const svg_shape_document *document,
                                     size_t first_edge, size_t edge_count,
                                     bool *formed)
{
    if (formed != NULL) *formed = false;
    if (edge_count == 0U || document == NULL || document->edges == NULL ||
        first_edge > document->edge_count ||
        edge_count > document->edge_count - first_edge) return NULL;
    if (formed != NULL) *formed = true;
    return &document->edges[first_edge];
}

static size_t cache_hash(uint32_t token_index, double viewport_width,
                        double viewport_height)
{
    uint64_t width_bits = 0U, height_bits = 0U;
    memcpy(&width_bits, &viewport_width, sizeof(width_bits));
    memcpy(&height_bits, &viewport_height, sizeof(height_bits));
    uint64_t value = (uint64_t)token_index ^ width_bits ^
                     (height_bits + UINT64_C(0x9e3779b97f4a7c15));
    value ^= value >> 30U;
    value *= UINT64_C(0xbf58476d1ce4e5b9);
    value ^= value >> 27U;
    value *= UINT64_C(0x94d049bb133111eb);
    value ^= value >> 31U;
    return (size_t)value & (SVG_PAINT_CACHE_SLOT_COUNT - 1U);
}

static svg_shape_error cache_create(svg_paint_cache **out)
{
    if (out == NULL) return SVG_SHAPE_ERROR_INVALID_ARGUMENT;
    if (*out != NULL) return SVG_SHAPE_ERROR_NONE;
    if (SVG_PAINT_CACHE_SLOT_COUNT > SIZE_MAX / sizeof(uint32_t))
        return SVG_SHAPE_ERROR_LIMIT;
    svg_paint_cache *cache = svg_shape_calloc(1U, sizeof(*cache));
    if (cache == NULL) return SVG_SHAPE_ERROR_OOM;
    cache->slots = svg_shape_calloc(SVG_PAINT_CACHE_SLOT_COUNT,
                                    sizeof(*cache->slots));
    if (cache->slots == NULL) {
        svg_shape_free(cache);
        return SVG_SHAPE_ERROR_OOM;
    }
    *out = cache;
    return SVG_SHAPE_ERROR_NONE;
}

static svg_cached_gradient *cache_find(svg_paint_cache *cache,
                                       uint32_t token_index,
                                       double viewport_width,
                                       double viewport_height)
{
    if (cache == NULL || cache->slots == NULL) return NULL;
    size_t slot = cache_hash(token_index, viewport_width, viewport_height);
    for (size_t probes = 0U; probes < SVG_PAINT_CACHE_SLOT_COUNT; ++probes) {
        uint32_t stored = cache->slots[slot];
        if (stored == 0U) return NULL;
        size_t entry = (size_t)(stored - 1U);
        if (entry < cache->entry_count &&
            cache->entries[entry].token_index == token_index &&
            cache->entries[entry].viewport_width == viewport_width &&
            cache->entries[entry].viewport_height == viewport_height)
            return &cache->entries[entry];
        slot = (slot + 1U) & (SVG_PAINT_CACHE_SLOT_COUNT - 1U);
    }
    return NULL;
}

static svg_shape_error cache_reserve_entry(svg_paint_cache *cache)
{
    if (cache->entry_count >= SVG_PAINT_CACHE_MAX_GRADIENTS ||
        cache->entry_count >= UINT32_MAX) return SVG_SHAPE_ERROR_LIMIT;
    if (cache->entry_count == cache->entry_capacity) {
        size_t capacity = cache->entry_capacity == 0U ? 16U :
                          cache->entry_capacity * 2U;
        if (capacity < cache->entry_capacity) return SVG_SHAPE_ERROR_LIMIT;
        if (capacity > SVG_PAINT_CACHE_MAX_GRADIENTS)
            capacity = SVG_PAINT_CACHE_MAX_GRADIENTS;
        if (capacity > SIZE_MAX / sizeof(*cache->entries))
            return SVG_SHAPE_ERROR_LIMIT;
        svg_cached_gradient *grown = svg_shape_realloc(
            cache->entries, capacity * sizeof(*cache->entries));
        if (grown == NULL) return SVG_SHAPE_ERROR_OOM;
        cache->entries = grown;
        cache->entry_capacity = capacity;
    }
    return SVG_SHAPE_ERROR_NONE;
}

static svg_shape_error cache_insert(svg_paint_cache *cache,
                                    const svg_cached_gradient *gradient,
                                    svg_cached_gradient **out)
{
    if (cache->entry_count >= cache->entry_capacity ||
        cache->entry_count >= SVG_PAINT_CACHE_MAX_GRADIENTS ||
        cache->entry_count >= UINT32_MAX) return SVG_SHAPE_ERROR_LIMIT;
    size_t entry = cache->entry_count;
    cache->entries[entry] = *gradient;
    size_t slot = cache_hash(gradient->token_index,
                             gradient->viewport_width,
                             gradient->viewport_height);
    for (size_t probes = 0U; probes < SVG_PAINT_CACHE_SLOT_COUNT; ++probes) {
        if (cache->slots[slot] == 0U) {
            cache->slots[slot] = (uint32_t)(entry + 1U);
            cache->entry_count++;
            *out = &cache->entries[entry];
            return SVG_SHAPE_ERROR_NONE;
        }
        slot = (slot + 1U) & (SVG_PAINT_CACHE_SLOT_COUNT - 1U);
    }
    return SVG_SHAPE_ERROR_LIMIT;
}

static bool eq(base_bytes source, svg_xml_span span, const char *text)
{
    size_t length = strlen(text);
    return span.offset <= source.len && span.length == length &&
           length <= source.len - span.offset &&
           memcmp(source.ptr + span.offset, text, length) == 0;
}

static bool attr(base_bytes source, const svg_xml_token *tokens, size_t count,
                 size_t element, const char *name, svg_xml_span *value)
{
    for (size_t i = element + 1U; i < count && tokens[i].kind == SVG_XML_TOKEN_ATTRIBUTE; ++i) {
        if (tokens[i].prefix.length == 0U && eq(source, tokens[i].local_name, name)) {
            *value = tokens[i].value;
            return true;
        }
    }
    return false;
}

static bool count_token_visit(size_t *token_visits)
{
    if (token_visits == NULL) return true;
    if (*token_visits >= SVG_PAINT_MAX_TOKEN_VISITS) return false;
    (*token_visits)++;
    return true;
}

static bool gradient_attributes_supported(base_bytes source,
                                          const svg_xml_token *tokens,
                                          size_t count, size_t gradient,
                                          bool linear,
                                          size_t *token_visits,
                                          bool *hit_limit)
{
    *hit_limit = false;
    for (size_t i = gradient + 1U;
         i < count && tokens[i].kind == SVG_XML_TOKEN_ATTRIBUTE; ++i) {
        if (!count_token_visit(token_visits)) {
            *hit_limit = true;
            return false;
        }
        svg_xml_span name = tokens[i].local_name;
        bool href = eq(source, name, "href") &&
            (tokens[i].prefix.length == 0U ||
             (eq(source, tokens[i].prefix, "xlink") &&
              svg_reference_xlink_is_bound(source, tokens, count)));
        bool common = tokens[i].prefix.length == 0U &&
            (eq(source, name, "id") || eq(source, name, "class") ||
             eq(source, name, "style") || eq(source, name, "gradientUnits") ||
             eq(source, name, "spreadMethod") ||
             eq(source, name, "gradientTransform"));
        bool coordinate = tokens[i].prefix.length == 0U &&
            (linear ? (eq(source, name, "x1") || eq(source, name, "y1") ||
                       eq(source, name, "x2") || eq(source, name, "y2")) :
                      (eq(source, name, "cx") || eq(source, name, "cy") ||
                       eq(source, name, "r") || eq(source, name, "fx") ||
                       eq(source, name, "fy")));
        if (!href && !common && !coordinate) return false;
    }
    return true;
}

static bool gradient_href(base_bytes source, const svg_xml_token *tokens,
                          size_t count, size_t gradient, bool *present,
                          svg_xml_span *value)
{
    *present = false;
    for (size_t i = gradient + 1U;
         i < count && tokens[i].kind == SVG_XML_TOKEN_ATTRIBUTE; ++i) {
        if (!eq(source, tokens[i].local_name, "href")) continue;
        if (*present ||
            (tokens[i].prefix.length != 0U &&
             (!eq(source, tokens[i].prefix, "xlink") ||
              !svg_reference_xlink_is_bound(source, tokens, count))) ||
            tokens[i].value.offset > source.len ||
            tokens[i].value.length < 2U ||
            tokens[i].value.length > source.len - tokens[i].value.offset ||
            source.ptr[tokens[i].value.offset] != '#') return false;
        *present = true;
        *value = tokens[i].value;
    }
    return true;
}

static svg_css_error gradient_inherited_color(
    svg_css_sheet *css, base_bytes source, const svg_xml_token *tokens,
    size_t count, size_t gradient, size_t *token_visits,
    svg_css_paint *color_style)
{
    size_t ancestors[64];
    size_t ancestor_count = 0U;
    for (size_t i = 0U; i <= gradient; ++i) {
        if (!count_token_visit(token_visits)) return SVG_CSS_LIMIT;
        if (tokens[i].kind != SVG_XML_TOKEN_START_ELEMENT &&
            tokens[i].kind != SVG_XML_TOKEN_EMPTY_ELEMENT) continue;
        while (ancestor_count != 0U &&
               tokens[ancestors[ancestor_count - 1U]].depth >= tokens[i].depth)
            ancestor_count--;
        if (ancestor_count == sizeof(ancestors) / sizeof(ancestors[0]))
            return SVG_CSS_LIMIT;
        ancestors[ancestor_count++] = i;
    }
    svg_css_paint inherited = svg_css_initial_paint();
    for (size_t i = 0U; i < ancestor_count; ++i) {
        svg_css_paint computed;
        svg_css_error error = svg_css_compute(css, source, tokens, count,
            ancestors[i], i == 0U ? NULL : &inherited, &computed);
        if (error != SVG_CSS_OK) return error;
        inherited = computed;
    }
    *color_style = (svg_css_paint){0};
    if (inherited.values[SVG_CSS_COLOR].present)
        color_style->values[SVG_CSS_COLOR] = inherited.values[SVG_CSS_COLOR];
    return SVG_CSS_OK;
}

static bool element_end(const svg_xml_token *tokens, size_t count, size_t start,
                        size_t *token_visits, size_t *end)
{
    if (tokens[start].kind == SVG_XML_TOKEN_EMPTY_ELEMENT) {
        *end = start;
        return true;
    }
    for (size_t i = start + 1U; i < count; ++i) {
        if (!count_token_visit(token_visits)) return false;
        if (tokens[i].kind == SVG_XML_TOKEN_END_ELEMENT &&
            tokens[i].depth == tokens[start].depth) {
            *end = i;
            return true;
        }
    }
    *end = start;
    return true;
}

static bool number(base_bytes source, svg_xml_span span, double *out)
{
    if (span.offset > source.len || span.length == 0U ||
        span.length >= 96U || span.length > source.len - span.offset) return false;
    char text[96];
    memcpy(text, source.ptr + span.offset, span.length);
    text[span.length] = '\0';
    char *end = NULL;
    *out = strtod(text, &end);
    if (end == text || !isfinite(*out) || fabs(*out) > 1000000.0) return false;
    bool percent = *end == '%';
    if (percent) ++end;
    if (*end != '\0') return false;
    if (percent) *out /= 100.0;
    return true;
}

static bool color(base_bytes source, svg_xml_span span, uint8_t rgba[4])
{
    return svg_css_parse_color(source, span, rgba);
}

static bool resolve_stop_color(base_bytes source, svg_xml_span span,
                               const svg_css_paint *style,
                               uint8_t rgba[4])
{
    if (!svg_css_keyword_equals(source, span, "currentColor"))
        return color(source, span, rgba);
    svg_xml_span color_value;
    if (!svg_css_paint_value(style, SVG_CSS_COLOR, &color_value) ||
        svg_css_keyword_equals(source, color_value, "currentColor")) {
        rgba[0] = rgba[1] = rgba[2] = 0U;
        rgba[3] = 255U;
        return true;
    }
    return color(source, color_value, rgba);
}

static bool supported_stop_inline_style(base_bytes source, svg_xml_span style)
{
    size_t i = style.offset, end = style.offset + style.length;
    while (i < end) {
        while (i < end && (source.ptr[i] == ' ' || source.ptr[i] == '\t' ||
                           source.ptr[i] == '\r' || source.ptr[i] == '\n' ||
                           source.ptr[i] == ';')) i++;
        if (i == end) break;
        size_t name = i;
        while (i < end && source.ptr[i] != ':' && source.ptr[i] != ';') i++;
        if (i == end || source.ptr[i] != ':') return false;
        size_t name_end = i;
        while (name_end > name && (source.ptr[name_end - 1U] == ' ' ||
                                   source.ptr[name_end - 1U] == '\t')) name_end--;
        svg_xml_span property = {name, name_end - name};
        if (!eq(source, property, "stop-color") &&
            !eq(source, property, "stop-opacity") &&
            !eq(source, property, "color")) return false;
        i++;
        while (i < end && source.ptr[i] != ';') i++;
        if (i < end) i++;
    }
    return true;
}

static bool parse_stops(svg_css_sheet *css, base_bytes source,
                        const svg_xml_token *tokens, size_t count,
                        size_t gradient, const svg_css_paint *gradient_style,
                        size_t *token_visits,
                        svg_paint_stop stops[SVG_PAINT_MAX_GRADIENT_STOPS],
                        size_t *stop_count, bool *has_stop_elements,
                        bool *hit_limit, bool *hit_oom)
{
    *has_stop_elements = false;
    *hit_limit = false;
    *hit_oom = false;
    size_t end = gradient;
    if (!element_end(tokens, count, gradient, token_visits, &end)) {
        *hit_limit = true;
        return false;
    }
    size_t n = 0U;
    for (size_t i = gradient + 1U; i < end; ++i) {
        if (!count_token_visit(token_visits)) {
            *hit_limit = true;
            return false;
        }
        if ((tokens[i].kind != SVG_XML_TOKEN_START_ELEMENT &&
             tokens[i].kind != SVG_XML_TOKEN_EMPTY_ELEMENT) ||
            tokens[i].depth != tokens[gradient].depth + 1U) continue;
        *has_stop_elements = true;
        if (!eq(source, tokens[i].local_name, "stop") ||
            tokens[i].prefix.length != 0U) return false;
        if (n == SVG_PAINT_MAX_GRADIENT_STOPS) { *hit_limit = true; return false; }
        svg_xml_span offset = {0}, stop_color = {0}, opacity = {0}, style = {0};
        (void)attr(source, tokens, count, i, "offset", &offset);
        if (attr(source, tokens, count, i, "style", &style) &&
            !supported_stop_inline_style(source, style)) return false;
        svg_css_paint computed;
        svg_css_error css_error = svg_css_compute(css, source, tokens, count, i,
                                                 gradient_style, &computed);
        if (css_error != SVG_CSS_OK) {
            *hit_limit = css_error == SVG_CSS_LIMIT;
            *hit_oom = css_error == SVG_CSS_OOM;
            return false;
        }
        for (size_t property = 0U; property < SVG_CSS_PROPERTY_COUNT; ++property) {
            if (property != SVG_CSS_STOP_COLOR &&
                property != SVG_CSS_STOP_OPACITY && property != SVG_CSS_COLOR &&
                computed.values[property].present) return false;
        }
        bool has_stop_color = svg_css_paint_value(
            &computed, SVG_CSS_STOP_COLOR, &stop_color);
        bool has_opacity = svg_css_paint_value(
            &computed, SVG_CSS_STOP_OPACITY, &opacity);
        double position = 0.0, alpha = 1.0;
        if (offset.length != 0U && !number(source, offset, &position)) return false;
        if (has_opacity && !number(source, opacity, &alpha)) return false;
        if (position < 0.0 || position > 1.0 || alpha < 0.0 || alpha > 1.0 ||
            (n != 0U && position < stops[n - 1U].offset)) return false;
        if (!has_stop_color) {
            stops[n].rgba[0] = stops[n].rgba[1] = stops[n].rgba[2] = 0U;
            stops[n].rgba[3] = 255U;
        } else if (stop_color.length == 0U ||
                   !resolve_stop_color(source, stop_color, &computed,
                                       stops[n].rgba))
            return false;
        stops[n].offset = position;
        stops[n].rgba[3] = (uint8_t)lround((double)stops[n].rgba[3] * alpha);
        ++n;
        if (tokens[i].kind == SVG_XML_TOKEN_START_ELEMENT) {
            size_t stop_end = i;
            if (!element_end(tokens, count, i, token_visits, &stop_end)) {
                *hit_limit = true;
                return false;
            }
            i = stop_end;
        }
    }
    if (n < 2U) return false;
    *stop_count = n;
    return true;
}

static bool gradient_coordinates(base_bytes source, const svg_xml_token *tokens,
                                 size_t count, const size_t *chain,
                                 size_t chain_count, bool object_box,
                                 double viewport_width, double viewport_height,
                                 svg_shape_paint *paint)
{
    static const char *const linear_names[4] = {"x1", "y1", "x2", "y2"};
    static const char *const radial_names[5] = {"cx", "cy", "r", "fx", "fy"};
    const char *const *names = paint->kind == SVG_SHAPE_PAINT_LINEAR ?
        linear_names : radial_names;
    double diagonal = hypot(viewport_width, viewport_height) / sqrt(2.0);
    double defaults[5] = {0.0};
    if (paint->kind == SVG_SHAPE_PAINT_LINEAR) {
        defaults[2] = object_box ? 1.0 : viewport_width;
    } else {
        defaults[0] = object_box ? 0.5 : viewport_width * 0.5;
        defaults[1] = object_box ? 0.5 : viewport_height * 0.5;
        defaults[2] = object_box ? 0.5 : diagonal * 0.5;
        defaults[3] = defaults[0];
        defaults[4] = defaults[1];
    }
    size_t coordinate_count = paint->kind == SVG_SHAPE_PAINT_LINEAR ? 4U : 5U;
    bool coordinate_found[5] = {false, false, false, false, false};
    for (size_t coordinate = 0U; coordinate < coordinate_count; ++coordinate) {
        paint->coordinates[coordinate] = defaults[coordinate];
        for (size_t definition = 0U; definition < chain_count; ++definition) {
            svg_xml_span value;
            if (!attr(source, tokens, count, chain[definition],
                      names[coordinate], &value)) continue;
            coordinate_found[coordinate] = true;
            double reference = object_box ? 1.0 :
                (paint->kind == SVG_SHAPE_PAINT_LINEAR ?
                    ((coordinate & 1U) == 0U ? viewport_width : viewport_height) :
                    coordinate == 2U ? diagonal :
                    (coordinate == 0U || coordinate == 3U ?
                        viewport_width : viewport_height));
            if (object_box) {
                size_t end = value.offset + value.length;
                for (size_t at = value.offset; at < end; ++at) {
                    uint8_t byte = source.ptr[at];
                    if ((byte >= 'a' && byte <= 'z') ||
                        (byte >= 'A' && byte <= 'Z')) return false;
                }
            }
            if (!svg_shape_read_length(source, value, reference,
                                       &paint->coordinates[coordinate]))
                return false;
            break;
        }
    }
    if (paint->kind == SVG_SHAPE_PAINT_RADIAL && !coordinate_found[3]) paint->coordinates[3] = paint->coordinates[0];
    if (paint->kind == SVG_SHAPE_PAINT_RADIAL && !coordinate_found[4]) paint->coordinates[4] = paint->coordinates[1];
    return paint->kind != SVG_SHAPE_PAINT_RADIAL ||
           (paint->coordinates[2] > 0.0 && isfinite(paint->coordinates[2]));
}

static bool collect_gradient_chain(base_bytes source,
                                   const svg_xml_token *tokens,
                                   size_t token_count,
                                   svg_reference_index *references,
                                   size_t target, bool linear,
                                   size_t *token_visits, size_t chain[16],
                                   size_t *chain_count, bool *hit_limit)
{
    *chain_count = 0U;
    *hit_limit = false;
    size_t current = target;
    while (true) {
        if (*chain_count == 16U) {
            *hit_limit = true;
            return false;
        }
        bool current_linear = eq(source, tokens[current].local_name,
                                 "linearGradient");
        bool current_radial = eq(source, tokens[current].local_name,
                                 "radialGradient");
        if ((!current_linear && !current_radial) || current_linear != linear ||
            tokens[current].prefix.length != 0U) return false;
        bool attr_limit = false;
        if (!gradient_attributes_supported(source, tokens, token_count,
                current, linear, token_visits, &attr_limit)) {
            *hit_limit = attr_limit;
            return false;
        }
        chain[(*chain_count)++] = current;
        bool has_href = false;
        svg_xml_span href = {0};
        if (!gradient_href(source, tokens, token_count, current,
                           &has_href, &href)) return false;
        if (!has_href) return true;
        svg_xml_span id = {href.offset + 1U, href.length - 1U};
        size_t parent;
        if (!svg_reference_index_find(source, tokens, token_count,
                                      references, id, &parent)) return false;
        for (size_t i = 0U; i < *chain_count; ++i)
            if (chain[i] == parent) return false;
        current = parent;
    }
}

svg_shape_error svg_paint_resolve_fill(base_bytes source,
                                       const svg_xml_token *tokens,
                                       size_t token_count,
                                       svg_reference_index *references,
                                       svg_css_sheet *css,
                                       svg_paint_cache **cache,
                                       size_t *token_visits,
                                       svg_xml_span fill,
                                       const geom_edge *edges, size_t edge_count,
                                       geom_affine user_inverse,
                                       double viewport_width, double viewport_height,
                                       svg_shape_paint *paint,
                                       svg_paint_stop **stops,
                                       size_t *stop_count,
                                       svg_shape_diagnostic *diagnostic)
{
    if (cache == NULL || stops == NULL || stop_count == NULL || paint == NULL) {
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_INVALID_ARGUMENT,
                                                 fill.offset};
        return SVG_SHAPE_ERROR_INVALID_ARGUMENT;
    }
    if (fill.length < 7U || fill.offset > source.len ||
        fill.length > source.len - fill.offset ||
        memcmp(source.ptr + fill.offset, "url(#", 5U) != 0 ||
        source.ptr[fill.offset + fill.length - 1U] != ')') return SVG_SHAPE_ERROR_UNSUPPORTED;
    svg_xml_span target_id = {fill.offset + 5U, fill.length - 6U};
    size_t target;
    if (!svg_reference_index_find(source, tokens, token_count, references,
                                  target_id, &target)) goto unsupported;
    if (target > UINT32_MAX) goto limit;
    bool linear = eq(source, tokens[target].local_name, "linearGradient");
    bool radial = eq(source, tokens[target].local_name, "radialGradient");
    if ((!linear && !radial) || tokens[target].prefix.length != 0U)
        goto unsupported;

    svg_cached_gradient *cached = cache_find(*cache, (uint32_t)target,
                                             viewport_width,
                                             viewport_height);
    if (cached == NULL) {
        svg_shape_error cache_error = cache_create(cache);
        if (cache_error == SVG_SHAPE_ERROR_LIMIT) goto limit;
        if (cache_error != SVG_SHAPE_ERROR_NONE) goto oom;

        size_t chain[16], chain_count = 0U;
        bool chain_limit = false;
        if (!collect_gradient_chain(source, tokens, token_count, references,
                target, linear, token_visits, chain, &chain_count,
                &chain_limit)) {
            if (chain_limit) goto limit;
            goto unsupported;
        }
        svg_shape_paint definition = {0};
        definition.kind = linear ? SVG_SHAPE_PAINT_LINEAR :
                                   SVG_SHAPE_PAINT_RADIAL;
        definition.object_bounding_box = true;
        definition.spread_method = SVG_SHAPE_SPREAD_PAD;
        definition.gradient_inverse = geom_affine_identity();
        bool found_units = false, found_spread = false, found_transform = false;
        for (size_t i = 0U; i < chain_count; ++i) {
            svg_xml_span value;
            if (!found_units && attr(source, tokens, token_count, chain[i],
                                     "gradientUnits", &value)) {
                if (eq(source, value, "userSpaceOnUse"))
                    definition.object_bounding_box = false;
                else if (!eq(source, value, "objectBoundingBox"))
                    goto unsupported;
                found_units = true;
            }
            if (!found_spread && attr(source, tokens, token_count, chain[i],
                                      "spreadMethod", &value)) {
                if (eq(source, value, "reflect"))
                    definition.spread_method = SVG_SHAPE_SPREAD_REFLECT;
                else if (eq(source, value, "repeat"))
                    definition.spread_method = SVG_SHAPE_SPREAD_REPEAT;
                else if (!eq(source, value, "pad"))
                    goto unsupported;
                found_spread = true;
            }
            if (!found_transform && attr(source, tokens, token_count, chain[i],
                                         "gradientTransform", &value)) {
                geom_affine transform;
                size_t operations = 0U;
                if (!svg_shape_transform_parse(source, value, &transform,
                                               &operations) ||
                    !svg_shape_affine_inverse(transform,
                                              &definition.gradient_inverse))
                    goto unsupported;
                (void)operations;
                found_transform = true;
            }
        }
        if (!gradient_coordinates(source, tokens, token_count, chain,
                chain_count, definition.object_bounding_box, viewport_width,
                viewport_height, &definition)) goto unsupported;

        svg_paint_stop local[SVG_PAINT_MAX_GRADIENT_STOPS];
        size_t local_count = 0U;
        bool inherited_stops = false;
        for (size_t i = 0U; i < chain_count; ++i) {
            svg_css_paint parent_color = {0};
            svg_css_error css_error = gradient_inherited_color(
                css, source, tokens, token_count, chain[i], token_visits,
                &parent_color);
            if (css_error == SVG_CSS_LIMIT) goto limit;
            if (css_error == SVG_CSS_OOM) goto oom;
            if (css_error != SVG_CSS_OK) goto unsupported;
            bool has_stop_elements = false, stop_limit = false, stop_oom = false;
            if (parse_stops(css, source, tokens, token_count, chain[i],
                    &parent_color, token_visits, local, &local_count,
                    &has_stop_elements, &stop_limit, &stop_oom)) {
                inherited_stops = true;
                break;
            }
            if (stop_limit) goto limit;
            if (stop_oom) goto oom;
            if (has_stop_elements) goto unsupported;
        }
        if (!inherited_stops) goto unsupported;
        if (*stop_count > SVG_PAINT_MAX_STOPS ||
            local_count > SVG_PAINT_MAX_STOPS - *stop_count) goto limit;
        cache_error = cache_reserve_entry(*cache);
        if (cache_error == SVG_SHAPE_ERROR_LIMIT) goto limit;
        if (cache_error != SVG_SHAPE_ERROR_NONE) goto oom;
        size_t new_stop_count = *stop_count + local_count;
        if (new_stop_count > SIZE_MAX / sizeof(**stops)) goto limit;
        svg_paint_stop *grown = svg_shape_realloc(
            *stops, new_stop_count * sizeof(**stops));
        if (grown == NULL) goto oom;
        size_t first_stop = *stop_count;
        memcpy(grown + first_stop, local, local_count * sizeof(*local));
        *stops = grown;
        *stop_count = new_stop_count;

        svg_cached_gradient pending = {0};
        pending.token_index = (uint32_t)target;
        pending.viewport_width = viewport_width;
        pending.viewport_height = viewport_height;
        pending.kind = definition.kind;
        pending.spread_method = definition.spread_method;
        pending.object_bounding_box = definition.object_bounding_box;
        memcpy(pending.coordinates, definition.coordinates,
               sizeof(pending.coordinates));
        pending.gradient_inverse = definition.gradient_inverse;
        pending.first_stop = first_stop;
        pending.stop_count = local_count;
        cache_error = cache_insert(*cache, &pending, &cached);
        if (cache_error == SVG_SHAPE_ERROR_LIMIT) goto limit;
        if (cache_error != SVG_SHAPE_ERROR_NONE) goto oom;
    }

    svg_shape_paint result = {0};
    result.kind = cached->kind;
    result.spread_method = cached->spread_method;
    result.object_bounding_box = cached->object_bounding_box;
    memcpy(result.coordinates, cached->coordinates, sizeof(result.coordinates));
    result.first_stop = cached->first_stop;
    result.stop_count = cached->stop_count;
    result.user_inverse = user_inverse;
    result.gradient_inverse = cached->gradient_inverse;
    if (edge_count == 0U) goto unsupported;
    geom_point first_local;
    if (!geom_affine_map_point(user_inverse, edges[0].a, &first_local))
        goto unsupported;
    double min_x = first_local.x, min_y = first_local.y;
    double max_x = min_x, max_y = min_y;
    for (size_t i = 0U; i < edge_count; ++i) {
        const geom_point source_points[2] = {edges[i].a, edges[i].b};
        for (size_t j = 0U; j < 2U; ++j) {
            geom_point point;
            if (!geom_affine_map_point(user_inverse, source_points[j], &point))
                goto unsupported;
            if (point.x < min_x) min_x = point.x;
            if (point.x > max_x) max_x = point.x;
            if (point.y < min_y) min_y = point.y;
            if (point.y > max_y) max_y = point.y;
        }
    }
    result.bounds[0] = min_x; result.bounds[1] = min_y;
    result.bounds[2] = max_x; result.bounds[3] = max_y;
    if (result.object_bounding_box && (max_x <= min_x || max_y <= min_y)) goto unsupported;
    *paint = result;
    return SVG_SHAPE_ERROR_NONE;
limit:
    if (diagnostic != NULL) *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_LIMIT, fill.offset};
    return SVG_SHAPE_ERROR_LIMIT;
oom:
    if (diagnostic != NULL) *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_OOM, fill.offset};
    return SVG_SHAPE_ERROR_OOM;
unsupported:
    if (diagnostic != NULL) *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_UNSUPPORTED, fill.offset};
    return SVG_SHAPE_ERROR_UNSUPPORTED;
}

void svg_paint_sample(const svg_shape_paint *paint, const svg_paint_stop *stops,
                      double x, double y, uint8_t rgba[4])
{
    if (paint == NULL || stops == NULL || paint->stop_count < 2U) return;
    geom_point local;
    if (!geom_affine_map_point(paint->user_inverse, (geom_point){x, y}, &local))
        return;
    double gx = local.x, gy = local.y, t;
    if (paint->object_bounding_box) {
        gx = (local.x - paint->bounds[0]) /
             (paint->bounds[2] - paint->bounds[0]);
        gy = (local.y - paint->bounds[1]) /
             (paint->bounds[3] - paint->bounds[1]);
    }
    geom_point transformed;
    if (!geom_affine_map_point(paint->gradient_inverse,
                               (geom_point){gx, gy}, &transformed)) return;
    gx = transformed.x;
    gy = transformed.y;
    if (paint->kind == SVG_SHAPE_PAINT_LINEAR) {
        double dx = paint->coordinates[2] - paint->coordinates[0];
        double dy = paint->coordinates[3] - paint->coordinates[1];
        double length = dx * dx + dy * dy;
        t = length == 0.0 ? 1.0 : ((gx - paint->coordinates[0]) * dx +
                                   (gy - paint->coordinates[1]) * dy) / length;
    } else {
        double focal_x = paint->coordinates[3];
        double focal_y = paint->coordinates[4];
        double center_dx = paint->coordinates[0] - focal_x;
        double center_dy = paint->coordinates[1] - focal_y;
        double point_dx = gx - focal_x;
        double point_dy = gy - focal_y;
        double radius = paint->coordinates[2];
        double a = center_dx * center_dx + center_dy * center_dy -
                   radius * radius;
        double b = -2.0 * (point_dx * center_dx + point_dy * center_dy);
        double c = point_dx * point_dx + point_dy * point_dy;
        if (fabs(a) <= 1e-15) {
            if (fabs(b) <= 1e-15) return;
            t = -c / b;
        } else {
            double discriminant = b * b - 4.0 * a * c;
            if (discriminant < 0.0 || !isfinite(discriminant)) return;
            double root = sqrt(discriminant);
            double t0 = (-b - root) / (2.0 * a);
            double t1 = (-b + root) / (2.0 * a);
            t = fmax(t0, t1);
            if (t < 0.0) t = fmin(t0, t1);
        }
    }
    if (!isfinite(t)) return;
    if (paint->spread_method == SVG_SHAPE_SPREAD_REPEAT) {
        t -= floor(t);
    } else if (paint->spread_method == SVG_SHAPE_SPREAD_REFLECT) {
        t = fmod(t, 2.0);
        if (t < 0.0) t += 2.0;
        if (t > 1.0) t = 2.0 - t;
    }
    if (t <= stops[paint->first_stop].offset) {
        memcpy(rgba, stops[paint->first_stop].rgba, 4U);
        return;
    }
    size_t last = paint->first_stop + paint->stop_count - 1U;
    if (t >= stops[last].offset) {
        memcpy(rgba, stops[last].rgba, 4U);
        return;
    }
    size_t right = paint->first_stop + 1U;
    while (right <= last && t > stops[right].offset) ++right;
    size_t left = right - 1U;
    double range = stops[right].offset - stops[left].offset;
    double amount = range <= 0.0 ? 1.0 : (t - stops[left].offset) / range;
    for (size_t c = 0U; c < 4U; ++c)
        rgba[c] = (uint8_t)lround((1.0 - amount) * stops[left].rgba[c] + amount * stops[right].rgba[c]);
}

use vexel_geometry::{Edge, Point, affine_map_point};
use vexel_scene::{Paint, PaintKind, PaintStop, Spread};

pub const MAX_STOPS: usize = 65_536;
pub const MAX_GRADIENT_STOPS: usize = 256;
pub const MAX_TOKEN_VISITS: usize = 4_194_304;

/// Checked equivalent of the legacy pointer span helper. `formed` is true
/// only when a nonempty in-range slice was formed.
pub fn edge_span<'a>(
    edges: &'a [Edge],
    first: usize,
    count: usize,
    formed: &mut bool,
) -> Option<&'a [Edge]> {
    *formed = false;
    if count == 0 {
        return None;
    }
    let end = first.checked_add(count)?;
    let result = edges.get(first..end)?;
    *formed = true;
    Some(result)
}

/// Validates a stop span before sampling. Invalid untrusted paint data or a
/// nonfinite intermediate leaves `rgba` unchanged, matching the C no-write
/// fallbacks without allowing an out-of-range access.
pub fn sample(paint: &Paint, stops: &[PaintStop], x: f64, y: f64, rgba: &mut [u8; 4]) {
    let Some(end) = paint.stops.first.checked_add(paint.stops.count) else {
        return;
    };
    if paint.stops.count < 2 || paint.stops.count > MAX_GRADIENT_STOPS || end > stops.len() {
        return;
    }
    let section = &stops[paint.stops.first..end];
    if !valid_stops(section) {
        return;
    }
    let Some(local) = affine_map_point(paint.user_inverse, Point { x, y }) else {
        return;
    };
    let (mut gx, mut gy) = (local.x, local.y);
    if paint.object_bounding_box {
        let (w, h) = (
            paint.bounds[2] - paint.bounds[0],
            paint.bounds[3] - paint.bounds[1],
        );
        if !w.is_finite() || !h.is_finite() || w <= 0.0 || h <= 0.0 {
            return;
        }
        gx = (local.x - paint.bounds[0]) / w;
        gy = (local.y - paint.bounds[1]) / h;
    }
    let Some(point) = affine_map_point(paint.gradient_inverse, Point { x: gx, y: gy }) else {
        return;
    };
    gx = point.x;
    gy = point.y;
    let t = match paint.kind {
        PaintKind::Linear => {
            let dx = paint.coordinates[2] - paint.coordinates[0];
            let dy = paint.coordinates[3] - paint.coordinates[1];
            let length = dx * dx + dy * dy;
            if length == 0.0 {
                1.0
            } else {
                ((gx - paint.coordinates[0]) * dx + (gy - paint.coordinates[1]) * dy) / length
            }
        }
        PaintKind::Radial => radial_t(paint, gx, gy),
        _ => return,
    };
    if !t.is_finite() {
        return;
    }
    let t = spread(t, paint.spread);
    if t <= section[0].offset {
        *rgba = section[0].rgba;
        return;
    }
    let last = section.len() - 1;
    if t >= section[last].offset {
        *rgba = section[last].rgba;
        return;
    }
    let mut right = 1;
    while right < last && t > section[right].offset {
        right += 1;
    }
    let left = right - 1;
    let range = section[right].offset - section[left].offset;
    let amount = if range <= 0.0 {
        1.0
    } else {
        (t - section[left].offset) / range
    };
    let mut output = [0; 4];
    for channel in 0..4 {
        output[channel] = ((1.0 - amount) * f64::from(section[left].rgba[channel])
            + amount * f64::from(section[right].rgba[channel]))
        .round()
        .clamp(0.0, 255.0) as u8;
    }
    *rgba = output;
}

fn valid_stops(stops: &[PaintStop]) -> bool {
    stops.len() >= 2
        && stops
            .iter()
            .all(|stop| stop.offset.is_finite() && (0.0..=1.0).contains(&stop.offset))
        && stops
            .windows(2)
            .all(|pair| pair[1].offset >= pair[0].offset)
}

fn spread(t: f64, spread: Spread) -> f64 {
    match spread {
        Spread::Pad => t,
        Spread::Repeat => t - t.floor(),
        Spread::Reflect => {
            let mut value = t % 2.0;
            if value < 0.0 {
                value += 2.0;
            }
            if value > 1.0 { 2.0 - value } else { value }
        }
    }
}

fn radial_t(paint: &Paint, gx: f64, gy: f64) -> f64 {
    let (cx, cy, radius, fx, fy) = (
        paint.coordinates[0],
        paint.coordinates[1],
        paint.coordinates[2],
        paint.coordinates[3],
        paint.coordinates[4],
    );
    let (center_dx, center_dy, point_dx, point_dy) = (cx - fx, cy - fy, gx - fx, gy - fy);
    let a = center_dx * center_dx + center_dy * center_dy - radius * radius;
    let b = -2.0 * (point_dx * center_dx + point_dy * center_dy);
    let c = point_dx * point_dx + point_dy * point_dy;
    if a.abs() <= 1e-15 {
        if b.abs() <= 1e-15 {
            return f64::NAN;
        }
        return -c / b;
    }
    let discriminant = b * b - 4.0 * a * c;
    if discriminant < 0.0 || !discriminant.is_finite() {
        return f64::NAN;
    }
    let root = discriminant.sqrt();
    let t0 = (-b - root) / (2.0 * a);
    let t1 = (-b + root) / (2.0 * a);
    let t = t0.max(t1);
    if t < 0.0 { t0.min(t1) } else { t }
}
use crate::control::PaintControl;
use crate::{MAX_GRADIENT_STOPS, MAX_STOPS, MAX_TOKEN_VISITS};
use std::sync::Arc;
use vexel_base::{WorkControl, WorkKind};
use vexel_geometry::{affine_identity, affine_valid};
use vexel_scene::{
    AllocationTag, Diagnostic, ElementId, ErrorKind, GradientCacheContext, GradientCacheEntry,
    LimitKind, Paint, PaintCache, PaintKind, PaintStop, Result, SourceOwner, TableRange,
};

pub(crate) const MAX_GRADIENTS: usize = 32_768;
pub(crate) const CACHE_SLOTS: usize = MAX_GRADIENTS * 2;

pub(crate) fn invalid(offset: usize) -> Diagnostic {
    Diagnostic {
        kind: ErrorKind::InvalidArgument,
        offset,
    }
}
pub(crate) fn unsupported(offset: usize) -> Diagnostic {
    Diagnostic {
        kind: ErrorKind::Unsupported,
        offset,
    }
}
pub(crate) fn limit(kind: LimitKind, offset: usize) -> Diagnostic {
    Diagnostic {
        kind: ErrorKind::Limit(kind),
        offset,
    }
}
pub(crate) fn oom(offset: usize) -> Diagnostic {
    Diagnostic {
        kind: ErrorKind::OutOfMemory,
        offset,
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Key {
    definition: u32,
    width: u64,
    height: u64,
}

fn key(definition: ElementId, viewport: [f64; 2], offset: usize) -> Result<Key> {
    if definition.0 > u32::MAX as usize {
        return Err(limit(LimitKind::PaintVisits, offset));
    }
    if !viewport
        .into_iter()
        .all(|value| value.is_finite() && value > 0.0)
    {
        return Err(unsupported(offset));
    }
    Ok(Key {
        definition: definition.0 as u32,
        width: viewport[0].to_bits(),
        height: viewport[1].to_bits(),
    })
}

fn hash(key: Key) -> usize {
    let mut value =
        u64::from(key.definition) ^ key.width ^ key.height.wrapping_add(0x9e37_79b9_7f4a_7c15);
    value ^= value >> 30;
    value = value.wrapping_mul(0xbf58_476d_1ce4_e5b9);
    value ^= value >> 27;
    value = value.wrapping_mul(0x94d0_49bb_1331_11eb);
    value ^= value >> 31;
    value as usize & (CACHE_SLOTS - 1)
}

pub(crate) fn token_visit(
    cache: &mut PaintCache,
    control: &mut PaintControl<'_>,
    offset: usize,
) -> Result<()> {
    let next = cache
        .token_visits
        .checked_add(1)
        .ok_or_else(|| limit(LimitKind::Arithmetic, offset))?;
    if next > MAX_TOKEN_VISITS {
        return Err(limit(LimitKind::PaintVisits, offset));
    }
    control
        .charge(WorkKind::TokenVisit, 1)
        .map_err(|_| limit(LimitKind::Work, offset))?;
    cache.token_visits = next;
    Ok(())
}

pub(crate) fn probe(control: &mut PaintControl<'_>, offset: usize) -> Result<()> {
    control
        .charge(WorkKind::ReferenceProbe, 1)
        .map_err(|_| limit(LimitKind::Work, offset))
}

fn template_context(viewport: [f64; 2]) -> GradientCacheContext {
    GradientCacheContext {
        viewport,
        user_inverse: affine_identity(),
        bounds: [0.0; 4],
    }
}

fn entry_valid(
    entry: &GradientCacheEntry,
    source: &SourceOwner,
    key: Key,
    kind: PaintKind,
) -> bool {
    let context = entry.context;
    entry.definition.0 == key.definition as usize
        && Arc::ptr_eq(&entry.source, source)
        && context.viewport.map(f64::to_bits) == [key.width, key.height]
        && context.user_inverse == affine_identity()
        && context.bounds == [0.0; 4]
        && entry.stop_range == entry.paint.stops
        && entry.paint.user_inverse == affine_identity()
        && entry.paint.bounds == [0.0; 4]
        && affine_valid(entry.paint.gradient_inverse)
        && entry.paint.coordinates.into_iter().all(f64::is_finite)
        && (entry.paint.kind != PaintKind::Radial || entry.paint.coordinates[2] > 0.0)
        && entry.paint.pattern.is_none()
        && entry
            .stop_range
            .slice(&entry.stops)
            .is_some_and(valid_stops)
        && entry.stops.len() <= MAX_GRADIENT_STOPS
        && entry.paint.kind == kind
}

fn valid_stops(stops: &[PaintStop]) -> bool {
    stops.len() >= 2
        && stops
            .iter()
            .all(|stop| stop.offset.is_finite() && (0.0..=1.0).contains(&stop.offset))
        && stops
            .windows(2)
            .all(|pair| pair[1].offset >= pair[0].offset)
}

/// Find a source-owned template, validating every slot before indexing. The
/// cache is the accepted scene contract; there is no paint-local replacement.
pub(crate) fn find_template<'a>(
    cache: &'a PaintCache,
    source: &SourceOwner,
    definition: ElementId,
    viewport: [f64; 2],
    kind: PaintKind,
    control: &mut PaintControl<'_>,
    offset: usize,
) -> Result<Option<&'a GradientCacheEntry>> {
    if cache.entries.len() > MAX_GRADIENTS
        || cache.slots.len() > CACHE_SLOTS
        || cache.token_visits > MAX_TOKEN_VISITS
        || (!cache.entries.is_empty() && cache.slots.len() != CACHE_SLOTS)
    {
        return Err(limit(LimitKind::PaintVisits, offset));
    }
    let wanted = key(definition, viewport, offset)?;
    if cache.slots.is_empty() {
        return Ok(None);
    }
    let mut slot = hash(wanted);
    for _ in 0..CACHE_SLOTS {
        probe(control, offset)?;
        match cache.slots.get(slot).copied().flatten() {
            None => return Ok(None),
            Some(index) => {
                let entry = cache.entries.get(index).ok_or_else(|| invalid(offset))?;
                let candidate = key(entry.definition, entry.context.viewport, offset)
                    .map_err(|_| invalid(offset))?;
                if candidate == wanted && Arc::ptr_eq(&entry.source, source) {
                    if !entry_valid(entry, source, wanted, kind) {
                        return Err(invalid(offset));
                    }
                    return Ok(Some(entry));
                }
            }
        }
        slot = (slot + 1) & (CACHE_SLOTS - 1);
    }
    Ok(None)
}

/// Insert one resolved gradient template and admit its actual retained Vec
/// capacities to the current job ledger. The caller has already checked miss.
pub(crate) fn insert_template(
    cache: &mut PaintCache,
    source: &SourceOwner,
    definition: ElementId,
    viewport: [f64; 2],
    paint: Paint,
    stops: &[PaintStop],
    control: &mut PaintControl<'_>,
    offset: usize,
) -> Result<()> {
    let wanted = key(definition, viewport, offset)?;
    if cache.entries.len() >= MAX_GRADIENTS {
        return Err(limit(LimitKind::PaintVisits, offset));
    }
    if stops.len() > MAX_GRADIENT_STOPS {
        return Err(limit(LimitKind::PaintStops, offset));
    }
    let mut old_stops = 0usize;
    for entry in &cache.entries {
        control
            .charge(WorkKind::PaintVisit, 1)
            .map_err(|_| limit(LimitKind::Work, offset))?;
        old_stops = old_stops
            .checked_add(entry.stops.len())
            .ok_or_else(|| limit(LimitKind::Arithmetic, offset))?;
    }
    if old_stops > MAX_STOPS || stops.len() > MAX_STOPS - old_stops {
        return Err(limit(LimitKind::PaintStops, offset));
    }
    if !valid_stops(stops)
        || paint.stops
            != (TableRange {
                first: 0,
                count: stops.len(),
            })
    {
        return Err(invalid(offset));
    }
    if !cache.slots.is_empty() && cache.slots.len() != CACHE_SLOTS {
        return Err(invalid(offset));
    }
    let mut slot = hash(wanted);
    if !cache.slots.is_empty() {
        let mut available = false;
        for _ in 0..CACHE_SLOTS {
            probe(control, offset)?;
            if cache.slots[slot].is_none() {
                available = true;
                break;
            }
            slot = (slot + 1) & (CACHE_SLOTS - 1);
        }
        if !available {
            return Err(limit(LimitKind::PaintVisits, offset));
        }
    }
    let mut owned_stops = Vec::new();
    owned_stops
        .try_reserve_exact(stops.len())
        .map_err(|_| oom(offset))?;
    owned_stops.extend_from_slice(stops);

    let old_metadata = cache
        .entries
        .capacity()
        .checked_mul(std::mem::size_of::<GradientCacheEntry>())
        .and_then(|a| {
            cache
                .slots
                .capacity()
                .checked_mul(std::mem::size_of::<Option<usize>>())
                .and_then(|b| a.checked_add(b))
        })
        .ok_or_else(|| limit(LimitKind::Arithmetic, offset))?;
    let target_slots = cache.slots.capacity().max(CACHE_SLOTS);
    let target_entries = if cache.entries.len() < cache.entries.capacity() {
        cache.entries.capacity()
    } else {
        let doubled = if cache.entries.capacity() == 0 {
            16
        } else {
            cache
                .entries
                .capacity()
                .checked_mul(2)
                .ok_or_else(|| limit(LimitKind::Arithmetic, offset))?
        };
        doubled.min(MAX_GRADIENTS)
    };
    let after_metadata = target_entries
        .checked_mul(std::mem::size_of::<GradientCacheEntry>())
        .and_then(|a| {
            target_slots
                .checked_mul(std::mem::size_of::<Option<usize>>())
                .and_then(|b| a.checked_add(b))
        })
        .ok_or_else(|| limit(LimitKind::Arithmetic, offset))?;
    let stop_bytes = owned_stops
        .capacity()
        .checked_mul(std::mem::size_of::<PaintStop>())
        .ok_or_else(|| limit(LimitKind::Arithmetic, offset))?;
    let delta = after_metadata
        .checked_sub(old_metadata)
        .and_then(|bytes| bytes.checked_add(stop_bytes))
        .ok_or_else(|| limit(LimitKind::Arithmetic, offset))?;
    // Reserve the accounting lease before growing retained cache storage.
    let lease = control.ledger.admit(AllocationTag::None, delta)?;

    if cache
        .slots
        .try_reserve_exact(CACHE_SLOTS - cache.slots.len())
        .is_err()
        || cache
            .entries
            .try_reserve_exact(target_entries.saturating_sub(cache.entries.len()))
            .is_err()
    {
        let retained = cache
            .entries
            .capacity()
            .checked_mul(std::mem::size_of::<GradientCacheEntry>())
            .and_then(|a| {
                cache
                    .slots
                    .capacity()
                    .checked_mul(std::mem::size_of::<Option<usize>>())
                    .and_then(|b| a.checked_add(b))
            })
            .and_then(|after| after.checked_sub(old_metadata))
            .ok_or_else(|| limit(LimitKind::Arithmetic, offset))?;
        control.ledger.release(lease)?;
        if retained != 0 {
            let _retained_lease = control.ledger.admit(AllocationTag::None, retained)?;
        }
        return Err(oom(offset));
    }
    let actual_metadata = cache
        .entries
        .capacity()
        .checked_mul(std::mem::size_of::<GradientCacheEntry>())
        .and_then(|a| {
            cache
                .slots
                .capacity()
                .checked_mul(std::mem::size_of::<Option<usize>>())
                .and_then(|b| a.checked_add(b))
        })
        .ok_or_else(|| limit(LimitKind::Arithmetic, offset))?;
    let actual_delta = actual_metadata
        .checked_sub(old_metadata)
        .and_then(|bytes| {
            owned_stops
                .capacity()
                .checked_mul(std::mem::size_of::<PaintStop>())
                .and_then(|stops| bytes.checked_add(stops))
        })
        .ok_or_else(|| limit(LimitKind::Arithmetic, offset))?;
    let extra_lease = if actual_delta > delta {
        Some(
            control
                .ledger
                .admit(AllocationTag::None, actual_delta - delta)?,
        )
    } else {
        control.ledger.release(lease)?;
        None
    };
    let lease = if actual_delta <= delta {
        control.ledger.admit(AllocationTag::None, actual_delta)?
    } else {
        lease
    };
    cache.slots.resize(CACHE_SLOTS, None);
    let entry = GradientCacheEntry {
        definition,
        context: template_context(viewport),
        paint,
        stop_range: TableRange {
            first: 0,
            count: stops.len(),
        },
        stops: owned_stops,
        source: Arc::clone(source),
    };
    let index = cache.entries.len();
    cache.entries.push(entry);
    cache.slots[slot] = Some(index);
    let _ = lease;
    let _ = extra_lease;
    Ok(())
}
use crate::MAX_GRADIENT_STOPS;
use crate::cache::{self, invalid, limit, oom, unsupported};
use crate::control::PaintControl;
use crate::resolver::{eq, keyword, remap};
use vexel_base::Span;
use vexel_scene::{DecodeSource, ElementId, Paint, PaintKind, PaintStop, Result, Spread};
use vexel_svg_color::parse_color;
use vexel_svg_css::{CssPaint, Property};
use vexel_svg_values::{affine_inverse, parse_length, parse_transform};
use vexel_xml::{TokenKind, XmlSpan, XmlToken};

pub(crate) fn inherited_gradient_color(
    shared: &mut DecodeSource<'_>,
    gradient: ElementId,
    cache: &mut vexel_scene::PaintCache,
    control: &mut PaintControl<'_>,
    offset: usize,
) -> Result<Option<XmlSpan>> {
    let tokens = shared.tokens();
    let mut ancestors = [0usize; 64];
    let mut count = 0;
    for i in 0..=gradient.0 {
        cache::token_visit(cache, control, offset)?;
        let Some(token) = tokens.get(i) else {
            return Err(invalid(offset));
        };
        if !matches!(
            token.kind,
            TokenKind::StartElement | TokenKind::EmptyElement
        ) {
            continue;
        }
        while count > 0 && tokens[ancestors[count - 1]].depth >= token.depth {
            count -= 1;
        }
        if count == ancestors.len() {
            return Err(limit(vexel_scene::LimitKind::Depth, offset));
        }
        ancestors[count] = i;
        count += 1;
    }
    let mut parent: Option<CssPaint<'_>> = None;
    for index in &ancestors[..count] {
        let style = shared
            .compute_style(ElementId(*index), parent.as_ref(), control)
            .map_err(|error| remap(error, offset))?;
        parent = Some(style);
    }
    Ok(parent.and_then(|style| style.value(Property::Color).map(|value| value.span)))
}

pub(crate) fn collect_stops(
    shared: &mut DecodeSource<'_>,
    chain: &[ElementId],
    cache: &mut vexel_scene::PaintCache,
    control: &mut PaintControl<'_>,
    offset: usize,
) -> Result<(Vec<PaintStop>, usize)> {
    for gradient in chain {
        let inherited_color = inherited_gradient_color(shared, *gradient, cache, control, offset)?;
        let end = element_end(shared.tokens(), gradient.0, cache, control, offset)?;
        let mut values = [PaintStop {
            offset: 0.0,
            rgba: [0; 4],
        }; MAX_GRADIENT_STOPS];
        let mut count = 0;
        let mut has_children = false;
        for i in gradient.0.saturating_add(1)..end {
            cache::token_visit(cache, control, offset)?;
            let token = &shared.tokens()[i];
            if !matches!(
                token.kind,
                TokenKind::StartElement | TokenKind::EmptyElement
            ) || token.depth != shared.tokens()[gradient.0].depth + 1
            {
                continue;
            }
            has_children = true;
            if token.prefix.length != 0 || !eq(shared.source(), token.local_name, b"stop") {
                return Err(unsupported(offset));
            }
            if count == MAX_GRADIENT_STOPS {
                return Err(limit(vexel_scene::LimitKind::PaintStops, offset));
            }
            let source = shared.source();
            let tokens = shared.tokens();
            let offset_span = attr(source, tokens, i, b"offset");
            let color_span = attr(source, tokens, i, b"stop-color");
            let opacity_span = attr(source, tokens, i, b"stop-opacity");
            if let Some(style) = attr(source, tokens, i, b"style") {
                if !supported_stop_inline_style(source, style) {
                    return Err(unsupported(offset));
                }
            }
            let computed = shared
                .compute_style(ElementId(i), None, control)
                .map_err(|error| remap(error, offset))?;
            for property in Property::ALL {
                if !matches!(
                    property,
                    Property::StopColor | Property::StopOpacity | Property::Color
                ) && computed.value(property).is_some()
                {
                    return Err(unsupported(offset));
                }
            }
            let computed_offset = computed
                .value(Property::StopColor)
                .map(|v| v.span)
                .or(color_span);
            let computed_opacity = computed
                .value(Property::StopOpacity)
                .map(|v| v.span)
                .or(opacity_span);
            let position = offset_span
                .filter(|span| span.length != 0)
                .map_or(Some(0.0), |v| number(shared.source(), v))
                .ok_or_else(|| unsupported(offset))?;
            let alpha = computed_opacity
                .map_or(Some(1.0), |v| number(shared.source(), v))
                .ok_or_else(|| unsupported(offset))?;
            if !(0.0..=1.0).contains(&position)
                || !(0.0..=1.0).contains(&alpha)
                || (count > 0 && position < values[count - 1].offset)
            {
                return Err(unsupported(offset));
            }
            let color = if let Some(span) = computed_offset {
                resolve_stop_color(
                    shared.source(),
                    span,
                    computed
                        .value(Property::Color)
                        .map(|v| v.span)
                        .or(inherited_color),
                )?
            } else {
                [0, 0, 0, 255]
            };
            values[count] = PaintStop {
                offset: position,
                rgba: [
                    color[0],
                    color[1],
                    color[2],
                    (f64::from(color[3]) * alpha).round().clamp(0.0, 255.0) as u8,
                ],
            };
            count += 1;
        }
        if count >= 2 {
            let mut owned = Vec::new();
            owned.try_reserve_exact(count).map_err(|_| oom(offset))?;
            owned.extend_from_slice(&values[..count]);
            return Ok((owned, count));
        }
        if has_children {
            return Err(unsupported(offset));
        }
    }
    Err(unsupported(offset))
}

fn element_end(
    tokens: &[XmlToken],
    start: usize,
    cache: &mut vexel_scene::PaintCache,
    control: &mut PaintControl<'_>,
    offset: usize,
) -> Result<usize> {
    let token = tokens.get(start).ok_or_else(|| invalid(offset))?;
    if token.kind == TokenKind::EmptyElement {
        return Ok(start);
    }
    for i in start.saturating_add(1)..tokens.len() {
        cache::token_visit(cache, control, offset)?;
        if tokens[i].kind == TokenKind::EndElement && tokens[i].depth == token.depth {
            return Ok(i);
        }
    }
    Ok(start)
}

pub(crate) fn read_definition_attributes(
    source: &[u8],
    tokens: &[XmlToken],
    chain: &[ElementId],
    paint: &mut Paint,
    offset: usize,
) -> Result<()> {
    let (mut units, mut spread, mut transform) = (false, false, false);
    for element in chain {
        if !units {
            if let Some(value) = attr(source, tokens, element.0, b"gradientUnits") {
                if eq(source, value, b"userSpaceOnUse") {
                    paint.object_bounding_box = false;
                } else if !eq(source, value, b"objectBoundingBox") {
                    return Err(unsupported(offset));
                }
                units = true;
            }
        }
        if !spread {
            if let Some(value) = attr(source, tokens, element.0, b"spreadMethod") {
                paint.spread = if eq(source, value, b"reflect") {
                    Spread::Reflect
                } else if eq(source, value, b"repeat") {
                    Spread::Repeat
                } else if eq(source, value, b"pad") {
                    Spread::Pad
                } else {
                    return Err(unsupported(offset));
                };
                spread = true;
            }
        }
        if !transform {
            if let Some(value) = attr(source, tokens, element.0, b"gradientTransform") {
                let span = Span::from_offset_length(value.offset, value.length)
                    .ok_or_else(|| invalid(offset))?;
                let (matrix, _) =
                    parse_transform(source, span).map_err(|error| unsupported(error.offset))?;
                paint.gradient_inverse =
                    affine_inverse(matrix).ok_or_else(|| unsupported(offset))?;
                transform = true;
            }
        }
    }
    Ok(())
}

pub(crate) fn read_coordinates(
    source: &[u8],
    tokens: &[XmlToken],
    chain: &[ElementId],
    viewport: [f64; 2],
    paint: &mut Paint,
    offset: usize,
) -> Result<()> {
    let linear = paint.kind == PaintKind::Linear;
    let names: [&[u8]; 5] = if linear {
        [b"x1", b"y1", b"x2", b"y2", b""]
    } else {
        [b"cx", b"cy", b"r", b"fx", b"fy"]
    };
    let diagonal = viewport[0].hypot(viewport[1]) / std::f64::consts::SQRT_2;
    if linear {
        paint.coordinates[2] = if paint.object_bounding_box {
            1.0
        } else {
            viewport[0]
        };
    } else {
        paint.coordinates[0] = if paint.object_bounding_box {
            0.5
        } else {
            viewport[0] * 0.5
        };
        paint.coordinates[1] = if paint.object_bounding_box {
            0.5
        } else {
            viewport[1] * 0.5
        };
        paint.coordinates[2] = if paint.object_bounding_box {
            0.5
        } else {
            diagonal * 0.5
        };
        paint.coordinates[3] = paint.coordinates[0];
        paint.coordinates[4] = paint.coordinates[1];
    }
    let count = if linear { 4 } else { 5 };
    let mut found = [false; 5];
    for coordinate in 0..count {
        for element in chain {
            let Some(value) = attr(source, tokens, element.0, names[coordinate]) else {
                continue;
            };
            found[coordinate] = true;
            let reference = if paint.object_bounding_box {
                1.0
            } else if linear {
                if coordinate % 2 == 0 {
                    viewport[0]
                } else {
                    viewport[1]
                }
            } else if coordinate == 2 {
                diagonal
            } else if coordinate == 0 || coordinate == 3 {
                viewport[0]
            } else {
                viewport[1]
            };
            if paint.object_bounding_box
                && value
                    .slice(source)
                    .is_some_and(|raw| raw.iter().any(|byte| byte.is_ascii_alphabetic()))
            {
                return Err(unsupported(offset));
            }
            let span = Span::from_offset_length(value.offset, value.length)
                .ok_or_else(|| invalid(offset))?;
            paint.coordinates[coordinate] =
                parse_length(source, span, reference).map_err(|_| unsupported(offset))?;
            break;
        }
    }
    if !linear {
        if !found[3] {
            paint.coordinates[3] = paint.coordinates[0];
        }
        if !found[4] {
            paint.coordinates[4] = paint.coordinates[1];
        }
        if paint.coordinates[2] <= 0.0 || !paint.coordinates[2].is_finite() {
            return Err(unsupported(offset));
        }
    }
    Ok(())
}

fn supported_stop_inline_style(source: &[u8], span: XmlSpan) -> bool {
    let Some(bytes) = span.slice(source) else {
        return false;
    };
    let mut i = 0;
    while i < bytes.len() {
        while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\r' | b'\n' | b';') {
            i += 1;
        }
        if i == bytes.len() {
            break;
        }
        let start = i;
        while i < bytes.len() && bytes[i] != b':' && bytes[i] != b';' {
            i += 1;
        }
        if i == bytes.len() || bytes[i] != b':' {
            return false;
        }
        let mut end = i;
        while end > start && matches!(bytes[end - 1], b' ' | b'\t') {
            end -= 1;
        }
        if !matches!(
            &bytes[start..end],
            b"stop-color" | b"stop-opacity" | b"color"
        ) {
            return false;
        }
        i += 1;
        while i < bytes.len() && bytes[i] != b';' {
            i += 1;
        }
        if i < bytes.len() {
            i += 1;
        }
    }
    true
}

fn resolve_stop_color(source: &[u8], stop: XmlSpan, current: Option<XmlSpan>) -> Result<[u8; 4]> {
    if !keyword(source, stop, b"currentColor") {
        return parse_css_color(source, stop);
    }
    let Some(color) = current else {
        return Ok([0, 0, 0, 255]);
    };
    if keyword(source, color, b"currentColor") {
        return Ok([0, 0, 0, 255]);
    }
    parse_css_color(source, color)
}

fn parse_css_color(source: &[u8], span: XmlSpan) -> Result<[u8; 4]> {
    let base =
        Span::from_offset_length(span.offset, span.length).ok_or_else(|| invalid(span.offset))?;
    parse_color(source, base).ok_or_else(|| unsupported(span.offset))
}

fn number(source: &[u8], span: XmlSpan) -> Option<f64> {
    let raw = span.slice(source)?;
    if raw.is_empty() || raw.len() >= 96 {
        return None;
    }
    let text = std::str::from_utf8(raw).ok()?;
    let text = text.trim_start_matches(|c| matches!(c, ' ' | '\t' | '\r' | '\n' | '\u{000c}'));
    let (numeric, percent) = text.strip_suffix('%').map_or((text, false), |v| (v, true));
    let value: f64 = numeric.parse().ok()?;
    if !value.is_finite() || value.abs() > 1_000_000.0 {
        return None;
    }
    Some(if percent { value / 100.0 } else { value })
}

fn attr(source: &[u8], tokens: &[XmlToken], element: usize, name: &[u8]) -> Option<XmlSpan> {
    let mut i = element.checked_add(1)?;
    while tokens
        .get(i)
        .is_some_and(|token| token.kind == TokenKind::Attribute)
    {
        let token = &tokens[i];
        if token.prefix.length == 0 && eq(source, token.local_name, name) {
            return Some(token.value);
        }
        i += 1;
    }
    None
}

use crate::cache::{self, invalid, limit, oom, unsupported};
use crate::control::PaintControl;
use crate::gradient_data;
use std::sync::Arc;
use vexel_base::{WorkControl, WorkKind};
use vexel_geometry::{Affine, Edge, affine_identity, affine_map_point};
use vexel_scene::{
    DecodeSource, ElementId, Paint, PaintKind, ResolveContext, ResolvedPaint, Result, Spread,
    TableRange,
};
use vexel_xml::{TokenKind, XmlSpan, XmlToken};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PaintReference {
    Gradient(ElementId),
    Pattern(ElementId),
}

/// Classify a local paint-server URL for the gradient resolver or definition
/// planner. Patterns are returned explicitly and are never treated as solids.
pub fn classify_fill(
    ctx: &mut ResolveContext<'_, '_>,
    value: XmlSpan,
    control: &mut dyn WorkControl,
) -> Result<PaintReference> {
    ctx.validate().map_err(|error| remap(error, value.offset))?;
    let ResolveContext {
        shared,
        cache: _,
        ledger,
    } = ctx;
    let mut control = PaintControl::new(ledger, control);
    let result = classify_inner(shared, value, &mut control);
    control.result_at(result, value.offset)
}

/// Resolve one local linear/radial paint template, then rebind instance inverse
/// and edge bounds. The returned template witness lets the scene builder share
/// graph stop storage across fills and strokes in that scene.
pub fn resolve_fill(
    ctx: &mut ResolveContext<'_, '_>,
    value: XmlSpan,
    edges: &[Edge],
    user_inverse: Affine,
    viewport: [f64; 2],
    work: &mut dyn WorkControl,
) -> Result<ResolvedPaint> {
    ctx.validate().map_err(|error| remap(error, value.offset))?;
    let ResolveContext {
        shared,
        cache,
        ledger,
    } = ctx;
    let mut control = PaintControl::new(ledger, work);
    let result = resolve_inner(
        shared,
        cache,
        value,
        edges,
        user_inverse,
        viewport,
        &mut control,
    );
    control.result_at(result, value.offset)
}

fn classify_inner(
    shared: &mut DecodeSource<'_>,
    value: XmlSpan,
    control: &mut PaintControl<'_>,
) -> Result<PaintReference> {
    let source = shared.source();
    let raw = value.slice(source).ok_or_else(|| invalid(value.offset))?;
    if raw.len() < 7 || !raw.starts_with(b"url(#") || raw.last() != Some(&b')') {
        return Err(unsupported(value.offset));
    }
    let id = XmlSpan {
        offset: value.offset + 5,
        length: value.length - 6,
    };
    if id.length == 0 {
        return Err(unsupported(value.offset));
    }
    let target = shared
        .find_reference(id, control)
        .map_err(|error| remap(error, value.offset))?
        .ok_or_else(|| unsupported(value.offset))?;
    let token = shared
        .tokens()
        .get(target.0)
        .ok_or_else(|| invalid(value.offset))?;
    if token.prefix.length != 0 {
        return Err(unsupported(value.offset));
    }
    if eq(source, token.local_name, b"linearGradient")
        || eq(source, token.local_name, b"radialGradient")
    {
        Ok(PaintReference::Gradient(target))
    } else if eq(source, token.local_name, b"pattern") {
        Ok(PaintReference::Pattern(target))
    } else {
        Err(unsupported(value.offset))
    }
}

fn resolve_inner(
    shared: &mut DecodeSource<'_>,
    cache: &mut vexel_scene::PaintCache,
    value: XmlSpan,
    edges: &[Edge],
    user_inverse: Affine,
    viewport: [f64; 2],
    control: &mut PaintControl<'_>,
) -> Result<ResolvedPaint> {
    control
        .checkpoint()
        .map_err(|_| limit(vexel_scene::LimitKind::Work, value.offset))?;
    let reference = classify_inner(shared, value, control)?;
    let PaintReference::Gradient(target) = reference else {
        return Err(unsupported(value.offset));
    };
    let target_token = shared
        .tokens()
        .get(target.0)
        .ok_or_else(|| invalid(value.offset))?;
    let linear = eq(shared.source(), target_token.local_name, b"linearGradient");
    let template_id = shared
        .gradient_template_id(target, viewport, control)
        .map_err(|error| remap(error, value.offset))?;
    let source_owner = Arc::clone(shared.source_owner());

    if let Some(template) = cache::find_template(
        cache,
        &source_owner,
        target,
        viewport,
        if linear {
            PaintKind::Linear
        } else {
            PaintKind::Radial
        },
        control,
        value.offset,
    )? {
        let template_paint = template.paint;
        let mut owned_stops = Vec::new();
        owned_stops
            .try_reserve_exact(template.stops.len())
            .map_err(|_| oom(value.offset))?;
        owned_stops.extend_from_slice(&template.stops);
        let paint = bind_instance(template_paint, edges, user_inverse, value.offset, control)?;
        control
            .checkpoint()
            .map_err(|_| limit(vexel_scene::LimitKind::Work, value.offset))?;
        return Ok(ResolvedPaint {
            paint,
            stops: owned_stops,
            template: Some(template_id),
        });
    }

    let mut chain = [ElementId(0); 16];
    let chain_count = collect_chain(
        shared,
        target,
        linear,
        &mut chain,
        cache,
        control,
        value.offset,
    )?;
    let kind = if linear {
        PaintKind::Linear
    } else {
        PaintKind::Radial
    };
    let mut definition = Paint {
        kind,
        spread: Spread::Pad,
        object_bounding_box: true,
        coordinates: [0.0; 6],
        bounds: [0.0; 4],
        user_inverse: affine_identity(),
        gradient_inverse: affine_identity(),
        stops: TableRange::EMPTY,
        pattern: None,
        pattern_inverse: affine_identity(),
        pattern_opacity: 1.0,
    };
    gradient_data::read_definition_attributes(
        shared.source(),
        shared.tokens(),
        &chain[..chain_count],
        &mut definition,
        value.offset,
    )?;
    gradient_data::read_coordinates(
        shared.source(),
        shared.tokens(),
        &chain[..chain_count],
        viewport,
        &mut definition,
        value.offset,
    )?;
    let (mut stops, stop_count) =
        gradient_data::collect_stops(shared, &chain[..chain_count], cache, control, value.offset)?;
    if stop_count < 2 {
        return Err(unsupported(value.offset));
    }
    stops.truncate(stop_count);
    definition.stops = TableRange {
        first: 0,
        count: stop_count,
    };
    let template_paint = definition;
    control
        .checkpoint()
        .map_err(|_| limit(vexel_scene::LimitKind::Work, value.offset))?;
    cache::insert_template(
        cache,
        &source_owner,
        target,
        viewport,
        template_paint,
        &stops,
        control,
        value.offset,
    )?;
    let mut instance = bind_instance(template_paint, edges, user_inverse, value.offset, control)?;
    instance.stops = template_paint.stops;
    Ok(ResolvedPaint {
        paint: instance,
        stops,
        template: Some(template_id),
    })
}

fn bind_instance(
    mut paint: Paint,
    edges: &[Edge],
    inverse: Affine,
    offset: usize,
    control: &mut PaintControl<'_>,
) -> Result<Paint> {
    if edges.is_empty() {
        return Err(unsupported(offset));
    }
    let first = affine_map_point(inverse, edges[0].a).ok_or_else(|| unsupported(offset))?;
    let (mut min_x, mut min_y, mut max_x, mut max_y) = (first.x, first.y, first.x, first.y);
    for edge in edges {
        for point in [edge.a, edge.b] {
            control
                .charge(WorkKind::PaintVisit, 1)
                .map_err(|_| limit(vexel_scene::LimitKind::Work, offset))?;
            let p = affine_map_point(inverse, point).ok_or_else(|| unsupported(offset))?;
            min_x = min_x.min(p.x);
            min_y = min_y.min(p.y);
            max_x = max_x.max(p.x);
            max_y = max_y.max(p.y);
        }
    }
    paint.bounds = [min_x, min_y, max_x, max_y];
    paint.user_inverse = inverse;
    if paint.object_bounding_box && (max_x <= min_x || max_y <= min_y) {
        return Err(unsupported(offset));
    }
    Ok(paint)
}

fn collect_chain(
    shared: &mut DecodeSource<'_>,
    target: ElementId,
    linear: bool,
    chain: &mut [ElementId; 16],
    cache: &mut vexel_scene::PaintCache,
    control: &mut PaintControl<'_>,
    offset: usize,
) -> Result<usize> {
    let source = shared.source();
    let tokens = shared.tokens();
    let mut count = 0;
    let mut current = target;
    loop {
        if count == chain.len() {
            return Err(limit(vexel_scene::LimitKind::Depth, offset));
        }
        let token = tokens.get(current.0).ok_or_else(|| invalid(offset))?;
        let is_linear = eq(source, token.local_name, b"linearGradient");
        let is_radial = eq(source, token.local_name, b"radialGradient");
        if (!is_linear && !is_radial) || is_linear != linear || token.prefix.length != 0 {
            return Err(unsupported(offset));
        }
        attributes_supported(source, tokens, current.0, linear, cache, control, offset)?;
        chain[count] = current;
        count += 1;
        let Some(href) = gradient_href(source, tokens, current.0, offset)? else {
            return Ok(count);
        };
        let id = XmlSpan {
            offset: href.offset + 1,
            length: href.length - 1,
        };
        let parent = shared
            .find_reference(id, control)
            .map_err(|error| remap(error, offset))?
            .ok_or_else(|| unsupported(offset))?;
        if chain[..count].contains(&parent) {
            return Err(unsupported(offset));
        }
        current = parent;
    }
}

fn attributes_supported(
    source: &[u8],
    tokens: &[XmlToken],
    element: usize,
    linear: bool,
    cache: &mut vexel_scene::PaintCache,
    control: &mut PaintControl<'_>,
    offset: usize,
) -> Result<()> {
    let mut i = element
        .checked_add(1)
        .ok_or_else(|| limit(vexel_scene::LimitKind::Arithmetic, offset))?;
    while tokens
        .get(i)
        .is_some_and(|token| token.kind == TokenKind::Attribute)
    {
        cache::token_visit(cache, control, offset)?;
        let token = &tokens[i];
        let name = token.local_name;
        let href = eq(source, name, b"href")
            && (token.prefix.length == 0
                || (eq(source, token.prefix, b"xlink")
                    && vexel_svg_reference::xlink_is_bound(source, tokens)));
        let common = token.prefix.length == 0
            && [
                b"id".as_slice(),
                b"class",
                b"style",
                b"gradientUnits",
                b"spreadMethod",
                b"gradientTransform",
            ]
            .iter()
            .any(|n| eq(source, name, n));
        let coordinates: &[&[u8]] = if linear {
            &[b"x1", b"y1", b"x2", b"y2"]
        } else {
            &[b"cx", b"cy", b"r", b"fx", b"fy"]
        };
        let coordinate =
            token.prefix.length == 0 && coordinates.iter().any(|n| eq(source, name, n));
        if !href && !common && !coordinate {
            return Err(unsupported(offset));
        }
        i += 1;
    }
    Ok(())
}

fn gradient_href(
    source: &[u8],
    tokens: &[XmlToken],
    element: usize,
    offset: usize,
) -> Result<Option<XmlSpan>> {
    let mut found = None;
    let mut i = element
        .checked_add(1)
        .ok_or_else(|| limit(vexel_scene::LimitKind::Arithmetic, offset))?;
    while tokens
        .get(i)
        .is_some_and(|token| token.kind == TokenKind::Attribute)
    {
        let token = &tokens[i];
        if eq(source, token.local_name, b"href") {
            let span = token.value;
            let raw = span.slice(source).ok_or_else(|| invalid(offset))?;
            if found.is_some()
                || (token.prefix.length != 0
                    && (!eq(source, token.prefix, b"xlink")
                        || !vexel_svg_reference::xlink_is_bound(source, tokens)))
                || raw.len() < 2
                || raw[0] != b'#'
            {
                return Err(unsupported(offset));
            }
            found = Some(span);
        }
        i += 1;
    }
    Ok(found)
}

pub(crate) fn eq(source: &[u8], span: XmlSpan, text: &[u8]) -> bool {
    span.slice(source) == Some(text)
}
pub(crate) fn keyword(source: &[u8], span: XmlSpan, text: &[u8]) -> bool {
    vexel_svg_css::keyword_equals(source, span, text)
}

pub(crate) fn remap(error: vexel_scene::Diagnostic, offset: usize) -> vexel_scene::Diagnostic {
    vexel_scene::Diagnostic { offset, ..error }
}
use vexel_base::{Stop, WorkControl, WorkKind};
use vexel_scene::{ChargeLedger, Diagnostic, ErrorKind, Result};

/// Couples accepted job accounting to caller cancellation/work control.
pub(crate) struct PaintControl<'a> {
    pub(crate) ledger: &'a mut ChargeLedger,
    pub(crate) outer: &'a mut dyn WorkControl,
    failure: Option<Diagnostic>,
}

impl<'a> PaintControl<'a> {
    pub(crate) fn new(ledger: &'a mut ChargeLedger, outer: &'a mut dyn WorkControl) -> Self {
        Self {
            ledger,
            outer,
            failure: None,
        }
    }
    pub(crate) fn result_at<T>(&mut self, result: Result<T>, offset: usize) -> Result<T> {
        match result {
            Ok(value) => Ok(value),
            Err(error) => {
                let mut diagnostic = self.failure.take().unwrap_or(error);
                diagnostic.offset = offset;
                Err(diagnostic)
            }
        }
    }
}

impl WorkControl for PaintControl<'_> {
    fn charge(&mut self, kind: WorkKind, units: u64) -> std::result::Result<(), Stop> {
        if let Err(error) = self.ledger.work.charge(kind, units) {
            let stop = stop_for(&error);
            self.failure = Some(error);
            return Err(stop);
        }
        if let Err(stop) = self.outer.charge(kind, units) {
            self.failure = Some(from_stop(stop, 0));
            return Err(stop);
        }
        Ok(())
    }
    fn checkpoint(&mut self) -> std::result::Result<(), Stop> {
        if let Err(stop) = self.outer.checkpoint() {
            self.failure = Some(from_stop(stop, 0));
            return Err(stop);
        }
        Ok(())
    }
}

fn from_stop(stop: Stop, offset: usize) -> Diagnostic {
    let kind = match stop {
        Stop::Canceled => ErrorKind::Canceled,
        Stop::Overflow => ErrorKind::Limit(vexel_scene::LimitKind::Arithmetic),
        Stop::Limit => ErrorKind::Limit(vexel_scene::LimitKind::Work),
    };
    Diagnostic { kind, offset }
}

fn stop_for(error: &Diagnostic) -> Stop {
    match error.kind {
        ErrorKind::OutOfMemory => Stop::Limit,
        ErrorKind::Canceled => Stop::Canceled,
        ErrorKind::Limit(vexel_scene::LimitKind::Arithmetic) => Stop::Overflow,
        ErrorKind::Limit(_) => Stop::Limit,
        _ => Stop::Limit,
    }
}
